// Builds the stage bundle for the renderer (E06): dist-bundle/{stage.js, stage.css, fonts/*, index.html,
// manifest.json}. `scripts/sync-contracts.sh` copies it to backend/stage-bundle/<version>/.
import { copyFile, mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'vite';
import { buildManifest, pickFontFaces } from './manifest.mjs';

const pkg = fileURLToPath(new URL('..', import.meta.url));
const out = join(pkg, 'dist-bundle');
const require = createRequire(import.meta.url);

await build({ configFile: join(pkg, 'vite.bundle.config.ts') });

// Fonts: the families STAGE_FONT names, only the subsets a Thai/Latin render can use.
const fontPkgs = [
  ['@fontsource-variable/noto-sans-thai', ['thai', 'latin', 'latin-ext']],
  ['@fontsource-variable/noto-sans', ['latin', 'latin-ext']],
];
await mkdir(join(out, 'fonts'), { recursive: true });
const css = ['/* Bundled stage fonts (SIL OFL 1.1, fontsource). Generated by scripts/build-bundle.mjs. */'];
for (const [name, subsets] of fontPkgs) {
  const dir = dirname(require.resolve(`${name}/package.json`));
  const picked = pickFontFaces(await readFile(join(dir, 'index.css'), 'utf8'), subsets);
  if (picked.fonts.length !== subsets.length) throw new Error(`${name}: expected ${subsets.length} subsets`);
  for (const f of picked.fonts) await copyFile(join(dir, 'files', f), join(out, 'fonts', f));
  css.push(picked.css);
}
await writeFile(join(out, 'stage.css'), css.join('\n'));

await writeFile(
  join(out, 'index.html'),
  `<!doctype html>
<html lang="th">
<head>
<meta charset="utf-8">
<link rel="stylesheet" href="stage.css">
</head>
<body>
<div id="stage"></div>
<script src="stage.js"></script>
</body>
</html>
`,
);

async function walk(dir) {
  const items = await readdir(dir, { withFileTypes: true });
  const files = await Promise.all(
    items.map((d) => (d.isDirectory() ? walk(join(dir, d.name)) : [join(dir, d.name)])),
  );
  return files.flat();
}
const files = {};
for (const abs of await walk(out)) {
  const rel = relative(out, abs).split('\\').join('/');
  if (rel !== 'manifest.json') files[rel] = await readFile(abs);
}
const manifest = buildManifest(files);
await writeFile(join(out, 'manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`);
console.log(`stage bundle ${manifest.version} (${Object.keys(files).length} files) → ${relative(pkg, out)}`);
